mapper.select:
SELECT id, model_id, sub_menu_type, title, content_body, meta_json
FROM model_contents
WHERE model_id = #{modelId} AND sub_menu_type = #{subMenuType}

mapper.update:
UPDATE model_contents
SET title = #{title},
    content_body = #{contentBody},
    meta_json = #{metaJson}
WHERE id = #{id}
